-- SaranIndex.com Schema & Seed Data

-- 1. Blocks Table
CREATE TABLE IF NOT EXISTS `blocks` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `block_name` VARCHAR(100) NOT NULL,
    `hindi_name` VARCHAR(100),
    `slug` VARCHAR(100) UNIQUE,
    `pincode` VARCHAR(10),
    `total_panchayats` INT DEFAULT 0,
    `lgd_code` VARCHAR(20) DEFAULT NULL,
    `census_2001_code` VARCHAR(20) DEFAULT NULL,
    `census_2011_code` VARCHAR(20) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2. Panchayats Table
CREATE TABLE IF NOT EXISTS `panchayats` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `block_id` INT NOT NULL,
    `panchayat_name` VARCHAR(100) NOT NULL,
    `hindi_name` VARCHAR(100),
    `slug` VARCHAR(100) UNIQUE,
    `village` TEXT,
    `village_hindi` TEXT,
    `panchayat_samiti_no` VARCHAR(100),
    KEY `idx_panchayat_block_id` (`block_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 3. Villages Table
CREATE TABLE IF NOT EXISTS `villages` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `panchayat_id` INT NOT NULL,
    `village_name` VARCHAR(100) NOT NULL,
    `hindi_name` VARCHAR(100),
    `slug` VARCHAR(100) UNIQUE,
    `pincode` VARCHAR(10),
    KEY `idx_village_panchayat_id` (`panchayat_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 4. Categories Table
CREATE TABLE IF NOT EXISTS `categories` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `hindi_name` VARCHAR(100),
    `icon` VARCHAR(100),
    `slug` VARCHAR(100) UNIQUE,
    `section` ENUM('BUSINESS','PROFESSIONAL','GOVT','EDUCATION','HEALTHCARE','EMERGENCY','BANK','HOTEL') DEFAULT 'BUSINESS',
    `status` ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 5. Subcategories Table
CREATE TABLE IF NOT EXISTS `subcategories` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `category_id` INT NOT NULL,
    `name` VARCHAR(100) NOT NULL,
    `type` ENUM('PROFESSIONAL','BUSINESS') DEFAULT 'PROFESSIONAL',
    `hindi_name` VARCHAR(100),
    `slug` VARCHAR(100) UNIQUE,
    `keywords` TEXT,
    KEY `idx_subcat_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 6. Core Listings Table
CREATE TABLE IF NOT EXISTS `listings` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `category_id` INT NOT NULL,
    `subcategory_id` INT DEFAULT NULL,
    `block_id` INT DEFAULT NULL,
    `panchayat_id` INT DEFAULT NULL,
    `village_id` INT DEFAULT NULL,
    `title` VARCHAR(200) NOT NULL,
    `hindi_title` VARCHAR(200),
    `slug` VARCHAR(220) UNIQUE,
    `contact_person` VARCHAR(100),
    `mobile` VARCHAR(20) NOT NULL,
    `mobile_visibility` VARCHAR(20) DEFAULT 'PUBLIC',
    `whatsapp` VARCHAR(20),
    `email` VARCHAR(100),
    `website` VARCHAR(150),
    `address` TEXT,
    `pincode` VARCHAR(10),
    `map_link` TEXT,
    `business_hours` VARCHAR(150) DEFAULT '9:00 AM - 8:00 PM',
    `services` TEXT,
    `products` TEXT,
    `gst_no` VARCHAR(50),
    `udyam_no` VARCHAR(50),
    `cin_no` VARCHAR(50),
    `local_reg_no` VARCHAR(100),
    `description` TEXT,
    `cover_image` VARCHAR(255),
    `is_verified` ENUM('YES','NO') DEFAULT 'NO',
    `is_featured` ENUM('YES','NO') DEFAULT 'NO',
    `status` ENUM('ACTIVE','PENDING','REJECTED') DEFAULT 'ACTIVE',
    `plan_type` ENUM('FREE','GOLD','PLATINUM') DEFAULT 'FREE',
    `plan_expires_at` DATETIME DEFAULT NULL,

    `view_count` INT DEFAULT 0,
    `star_rating` DECIMAL(3,2) DEFAULT 5.00,
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY `idx_listing_category_id` (`category_id`),
    KEY `idx_listing_block_id` (`block_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 7. Reviews Table
CREATE TABLE IF NOT EXISTS `reviews` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `listing_id` INT NOT NULL,
    `reviewer_name` VARCHAR(100) NOT NULL,
    `reviewer_mobile` VARCHAR(20),
    `rating` INT CHECK (rating BETWEEN 1 AND 5),
    `comment` TEXT,
    `status` ENUM('APPROVED','PENDING') DEFAULT 'APPROVED',
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY `idx_review_listing_id` (`listing_id`)
-- 7.5. Public Users Table
CREATE TABLE IF NOT EXISTS `users` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `full_name` VARCHAR(100) NOT NULL,
    `mobile` VARCHAR(20) NOT NULL UNIQUE,
    `whatsapp` VARCHAR(20) DEFAULT NULL,
    `email` VARCHAR(100) DEFAULT NULL,
    `password_hash` VARCHAR(255) NOT NULL,
    `business_name` VARCHAR(150) DEFAULT NULL,
    `designation` VARCHAR(100) DEFAULT NULL,
    `block_id` INT DEFAULT NULL,
    `panchayat_id` INT DEFAULT NULL,
    `village_id` INT DEFAULT NULL,
    `address` TEXT DEFAULT NULL,
    `pincode` VARCHAR(10) DEFAULT NULL,
    `profile_image` VARCHAR(255) DEFAULT NULL,
    `bio` TEXT DEFAULT NULL,
    `status` ENUM('ACTIVE','INACTIVE','SUSPENDED') DEFAULT 'ACTIVE',
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `name` VARCHAR(150) DEFAULT NULL,
    `mobile_status` VARCHAR(20) DEFAULT 'UNVERIFIED',
    `mobile_visibility` VARCHAR(20) DEFAULT 'PUBLIC',
    `email_status` VARCHAR(20) DEFAULT 'UNVERIFIED',
    `email_visibility` VARCHAR(20) DEFAULT 'PUBLIC',
    `password` VARCHAR(255) DEFAULT NULL,
    `token` VARCHAR(255) DEFAULT NULL,
    `type` VARCHAR(50) DEFAULT 'USER',
    `address_visibility` VARCHAR(20) DEFAULT 'PUBLIC',
    `state_code` VARCHAR(20) DEFAULT NULL,
    `district_code` VARCHAR(20) DEFAULT NULL,
    `dob` DATE DEFAULT NULL,
    `r_name` VARCHAR(150) DEFAULT NULL,
    `education` VARCHAR(150) DEFAULT NULL,
    `gender` VARCHAR(20) DEFAULT NULL,
    `public_url` VARCHAR(255) DEFAULT NULL,
    `counter` INT DEFAULT 0,
    `univ_code` VARCHAR(50) DEFAULT NULL,
    `college_code` VARCHAR(50) DEFAULT NULL,
    `about` TEXT DEFAULT NULL,
    `photo` VARCHAR(255) DEFAULT NULL,
    `id_proof` VARCHAR(255) DEFAULT NULL,
    `wallet` DECIMAL(10,2) DEFAULT 0.00,
    `created_by` INT DEFAULT 0,
    `updated_by` INT DEFAULT 0,
    `plan_type` VARCHAR(50) DEFAULT NULL,
    `plan_expiry` DATETIME DEFAULT NULL,
    `languages` VARCHAR(255) DEFAULT NULL,
    `otp_code` VARCHAR(20) DEFAULT NULL,
    `otp_expiry` DATETIME DEFAULT NULL,
    `linkedin` VARCHAR(255) DEFAULT NULL,
    `twitter` VARCHAR(255) DEFAULT NULL,
    `facebook` VARCHAR(255) DEFAULT NULL,
    `instagram` VARCHAR(255) DEFAULT NULL,
    `google_maps_link` TEXT DEFAULT NULL,
    KEY `idx_user_block_id` (`block_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 7.6. Deleted Users Archive Table
CREATE TABLE IF NOT EXISTS `deleted_users` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `original_user_id` INT DEFAULT NULL,
    `full_name` VARCHAR(100) DEFAULT NULL,
    `mobile` VARCHAR(20) DEFAULT NULL,
    `whatsapp` VARCHAR(20) DEFAULT NULL,
    `email` VARCHAR(100) DEFAULT NULL,
    `password_hash` VARCHAR(255) DEFAULT NULL,
    `business_name` VARCHAR(150) DEFAULT NULL,
    `designation` VARCHAR(100) DEFAULT NULL,
    `block_id` INT DEFAULT NULL,
    `panchayat_id` INT DEFAULT NULL,
    `village_id` INT DEFAULT NULL,
    `address` TEXT DEFAULT NULL,
    `pincode` VARCHAR(10) DEFAULT NULL,
    `profile_image` VARCHAR(255) DEFAULT NULL,
    `bio` TEXT DEFAULT NULL,
    `status` VARCHAR(50) DEFAULT NULL,
    `type` VARCHAR(50) DEFAULT NULL,
    `wallet` DECIMAL(10,2) DEFAULT 0.00,
    `user_data_json` LONGTEXT DEFAULT NULL,
    `deleted_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    `deleted_by` VARCHAR(100) DEFAULT 'SYSTEM'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. Admins Table
CREATE TABLE IF NOT EXISTS `admins` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `username` VARCHAR(50) NOT NULL UNIQUE,
    `password_hash` VARCHAR(255) NOT NULL,
    `full_name` VARCHAR(100) NOT NULL,
    `email` VARCHAR(100),
    `role` ENUM('SUPER_ADMIN','MODERATOR') DEFAULT 'SUPER_ADMIN',
    `last_login` DATETIME NULL,
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 9. Contact Submissions Table
CREATE TABLE IF NOT EXISTS `contact` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(250) NOT NULL,
    `mobile` VARCHAR(20) NOT NULL,
    `email` VARCHAR(255) DEFAULT NULL,
    `subject` VARCHAR(254) DEFAULT NULL,
    `message` TEXT DEFAULT NULL,
    `mobile_status` VARCHAR(10) DEFAULT NULL,
    `status` VARCHAR(50) DEFAULT 'UNREAD',
    `profile_id` INT DEFAULT 0,
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    `created_by` INT DEFAULT 0,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `updated_by` INT DEFAULT 0,
    `reply` VARCHAR(1000) DEFAULT '',
    `reply_message` TEXT DEFAULT NULL,
    `replied_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 10. People Table
CREATE TABLE IF NOT EXISTS `people` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `full_name` VARCHAR(120) NOT NULL,
    `hindi_name` VARCHAR(120) DEFAULT NULL,
    `slug` VARCHAR(150) UNIQUE,
    `designation` VARCHAR(100) DEFAULT NULL,
    `profession` VARCHAR(100) DEFAULT NULL,
    `mobile` VARCHAR(20) NOT NULL,
    `whatsapp` VARCHAR(20) DEFAULT NULL,
    `email` VARCHAR(100) DEFAULT NULL,
    `block_id` INT DEFAULT NULL,
    `panchayat_id` INT DEFAULT NULL,
    `village_id` INT DEFAULT NULL,
    `address` TEXT DEFAULT NULL,
    `pincode` VARCHAR(10) DEFAULT NULL,
    `photo` VARCHAR(255) DEFAULT NULL,
    `bio` TEXT DEFAULT NULL,
    `status` ENUM('ACTIVE','PENDING','INACTIVE') DEFAULT 'ACTIVE',
    `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY `idx_people_block_id` (`block_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;




